def copy_marketing_choices(apps,schema_editor):
    gate=apps.get_model('development','Gate2')
    channel=apps.get_model('development','Gate2MarketingChannel')
    alias=schema_editor.connection.alias
    channel_codes={'pop':'pop','дэлгүүрийн pop':'pop','social':'social','сошиал':'social','cu_app':'cu_app','cu апп':'cu_app','other':'other','бусад':'other'}
    promotion_codes={'discount':'discount','хөнгөлөлт':'discount','bogo':'bogo','1+1':'bogo','bundle':'bundle','багц':'bundle','tasting':'tasting','амталгаа':'tasting','other':'other','бусад':'other'}
    for record in gate.objects.using(alias).all().iterator():
        if not channel.objects.using(alias).filter(gate_id=record.pk).exists():
            values=[]
            for token in re.split(r'[,;·|\n]+',record.marketing_plan or ''):
                code=channel_codes.get(token.strip().casefold())
                if code and code not in values: values.append(code)
            channel.objects.using(alias).bulk_create([
                channel(gate_id=record.pk,position=position,value=value) for position,value in enumerate(values)])
        code=promotion_codes.get((record.marketing_promotion or '').strip().casefold())
        if code:
            updates={'marketing_promotion':code}
            if not record.marketing_has_promotion: updates['marketing_has_promotion']='yes'
            gate.objects.using(alias).filter(pk=record.pk).update(**updates)


